mkdir -p /work/repo/.railway && cat > /work/repo/.railway/railway.ts <<'EOF'
// Railway Infrastructure as Code for linkding.
// Preview with `railway config plan`, apply with `railway config apply`.
// Setup steps and cost notes: .railway/README.md
import { defineRailway, image, preserve, project, service, volume } from "railway/iac";

export default defineRailway(() => {
  // SQLite database, secret key, favicons, previews and uploaded assets all
  // live here. 1 GB is plenty for a personal instance; growing it later is
  // non-destructive, shrinking it is destructive.
  const data = volume("linkding-data", { sizeMB: 1024 });

  const linkding = service("linkding", {
    // This fork carries no code changes (see FORK-NOTES.md), so the published
    // upstream image for the same version (version.txt) is the same app, and
    // Railway doesn't have to build anything. Bump this tag when version.txt
    // changes.
    source: image("sissbruecker/linkding:1.46.2"),

    healthcheck: "/health",
    healthcheckTimeout: 120,
    // SQLite on a volume: exactly one instance.
    replicas: 1,
    deploy: {
      restartPolicyType: "ON_FAILURE",
      restartPolicyMaxRetries: 10,
      // Cap memory so a runaway process can't push the bill past the
      // Hobby plan's included $5 of usage. linkding normally needs ~150-250 MB.
      limitOverride: { containers: { memoryBytes: 512 * 1024 * 1024 } },
    },

    env: {
      // uwsgi listens on 9090. Railway routes the public domain to $PORT.
      PORT: "9090",
      LD_SERVER_PORT: "9090",
      // Railway terminates TLS, so Django sees plain HTTP while the browser
      // sends an https Origin header. Trust the service's own public domain so
      // logins and other POST requests pass the CSRF check. Railway resolves
      // the ${{ }} reference when it deploys.
      LD_CSRF_TRUSTED_ORIGINS: "https://${{RAILWAY_PUBLIC_DOMAIN}}",
      // Initial admin account. Set the values in the Railway dashboard, never
      // in this file. preserve() keeps whatever is set there across applies.
      LD_SUPERUSER_NAME: preserve(),
      LD_SUPERUSER_PASSWORD: preserve(),
    },

    volumeMounts: { "/etc/linkding/data": data },
  });

  return project("linkding", { resources: [linkding, data] });
});
EOF
